// src/jsx/PrivateChat.jsx
import React, { useEffect, useState, useRef } from "react";
import { db } from "../js/firebaseConfig";
import { collection, addDoc, serverTimestamp, query, orderBy, onSnapshot, doc, setDoc, getDoc, updateDoc, where, getDocs, arrayUnion } from "firebase/firestore";
import Avatar from "./Avatar";
import useSearchUsers from "../hooks/useSearchUsers";
import { uploadMessageMedia } from "../js/supabaseUpload";
import Picker from "emoji-picker-react";

function makeRoomId(a, b) { return [a, b].sort().join("_"); }

function formatTime(ts) {
    if (!ts) return "";
    if (ts?.toDate) return ts.toDate().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
    try { return new Date(ts).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }); }
    catch { return ""; }
}

export default function PrivateChat({ currentUser, otherUser, onClose }) {
    const roomId = makeRoomId(currentUser.uid, otherUser.id);
    const { allUsers } = useSearchUsers();
    const [messages, setMessages] = useState([]);
    const [text, setText] = useState("");
    const [file, setFile] = useState(null);
    const [previewUrl, setPreviewUrl] = useState("");
    const [uploading, setUploading] = useState(false);
    const [editingMessage, setEditingMessage] = useState(null);
    const [editText, setEditText] = useState("");
    const [showEmoji, setShowEmoji] = useState(false);
    const [showGifModal, setShowGifModal] = useState(false);
    const [gifUrl, setGifUrl] = useState("");
    const listRef = useRef(null);

    useEffect(() => {
        let unsub;
        const setupChat = async () => {
            const roomDocRef = doc(db, "rooms", roomId);
            const roomSnap = await getDoc(roomDocRef);

            if (!roomSnap.exists()) {
                await setDoc(roomDocRef, {
                    members: [currentUser.uid, otherUser.id],
                    createdAt: serverTimestamp(),
                    lastMessage: "",
                    lastUpdated: serverTimestamp()
                });
            }

            const messagesRef = collection(db, `rooms/${roomId}/messages`);
            const q = query(messagesRef, orderBy("createdAt", "asc"));

            unsub = onSnapshot(q, async snap => {
                const arr = snap.docs.map(d => ({ id: d.id, ...d.data() }));
                setMessages(arr);

                const batchUpdates = [];
                for (let d of snap.docs) {
                    const data = d.data();
                    if (!data) continue;
                    if (data.from !== currentUser.uid && data.status === "sent") {
                        batchUpdates.push(updateDoc(d.ref, { status: "received" }));
                    }
                }
                if (batchUpdates.length > 0) {
                    try { await Promise.all(batchUpdates); } catch (e) { /* ignore */ }
                }

                // scroll automático
                setTimeout(() => {
                    if (listRef.current) listRef.current.scrollTop = listRef.current.scrollHeight;
                }, 50);
            });

            // ao abrir o chat, marcar mensagens não vistas como 'seen'
            await markMessagesAsSeen(roomId, currentUser.uid);

        };

        setupChat();

        return () => {
            if (unsub) unsub();
            if (previewUrl) URL.revokeObjectURL(previewUrl);
        };
    }, [roomId]);

    async function markMessagesAsSeen(roomId, uid) {
        try {
            const messagesRef = collection(db, `rooms/${roomId}/messages`);
            const q = query(messagesRef, where("from", "!=", uid));
            const snap = await getDocs(q);

            const updates = [];
            for (let d of snap.docs) {
                const data = d.data();
                if (!data) continue;
                const seenBy = data.seenBy || [];
                if (!seenBy.includes(uid)) {
                    // adiciona uid em seenBy e coloca status 'seen'
                    updates.push(updateDoc(d.ref, {
                        seenBy: arrayUnion(uid),
                        status: "seen"
                    }));
                }
            }
            if (updates.length) await Promise.all(updates);
        } catch (err) {
            console.error("Erro marcando mensagens como seen:", err);
        }
    }

    // enviar texto/arquivo/gif
    const send = async () => {
        if (editingMessage) return saveEdit();
        if (!text.trim() && !file && !gifUrl) return;

        setUploading(true);

        try {
            let mediaUrl = "";
            let type = "text";
            let mediaPath = "";

            if (gifUrl) {
                mediaUrl = gifUrl;
                type = "gif";
            } else if (file) {
                const res = await uploadMessageMedia(file, roomId);
                if (typeof res === "string") {
                    mediaUrl = res;
                } else if (res?.publicUrl) {
                    mediaUrl = res.publicUrl;
                    mediaPath = res.path || "";
                } else {
                    mediaUrl = res?.publicUrl || "";
                }

                const lower = file.type.toLowerCase();
                if (lower.startsWith("image/")) type = "image";
                else if (lower.startsWith("video/")) type = "video";
                else if (lower.startsWith("audio/")) type = "audio";
                else type = "file";
            }

            await addDoc(collection(db, `rooms/${roomId}/messages`), {
                text: text?.trim() || "",
                type,
                url: mediaUrl || "",
                from: currentUser.uid,
                createdAt: serverTimestamp(),
                status: "sent",
                seenBy: [],
                edited: false,
                deletedFor: []
            });

            await setDoc(doc(db, "rooms", roomId), {
                lastMessage: text?.trim() || (type === "image" ? "[imagem]" : (type === "gif" ? "[gif]" : "[arquivo]")),
                lastUpdated: serverTimestamp()
            }, { merge: true });

            setText("");
            setFile(null);
            setGifUrl("");
            if (previewUrl) {
                URL.revokeObjectURL(previewUrl); setPreviewUrl("");
            }

        } catch (err) {
            console.error("Erro ao enviar mensagem:", err);
            alert("Erro ao enviar mensagem: " + (err.message || err));
        } finally {
            setUploading(false);
        }
    };

    const onSelectFile = (e) => {
        const f = e.target.files[0];
        if (!f) return;

        const maxMB = 40;
        if (f.size > maxMB * 1024 * 1024) {
            alert(`Arquivo muito grande (limite ${maxMB} MB).`);
            return;
        }

        setFile(f);
        const p = URL.createObjectURL(f);
        setPreviewUrl(p);
    };

    const startEditing = (msg) => {
        if (msg.from !== currentUser.uid) return alert("Só pode editar suas próprias mensagens.");
        const created = msg.createdAt?.toDate?.()?.getTime?.() || (msg.createdAt ? new Date(msg.createdAt).getTime() : 0);
        if (Date.now() - created > 5 * 60 * 1000) return alert("Só é possível editar mensagens até 5 minutos após envio.");

        setEditingMessage(msg);
        setEditText(msg.text || "");
        setText(msg.text || "");
    };

    const saveEdit = async () => {
        if (!editingMessage) return;

        try {
            await updateDoc(doc(db, `rooms/${roomId}/messages`, editingMessage.id), {
                text: editText.trim(),
                edited: true,
                editedAt: serverTimestamp()
            });

            await setDoc(doc(db, "rooms", roomId), {
                lastMessage: editText.trim() || "",
                lastUpdated: serverTimestamp()
            }, { merge: true });

            setEditingMessage(null);
            setEditText("");
            setText("");
        } catch (err) {
            console.error("Erro salvando edição:", err);
            alert("Erro ao editar: " + err.message);
        }
    };

    const cancelEdit = () => {
        setEditingMessage(null);
        setEditText("");
        setText("");
    };

    const deleteForMe = async (msg) => {
        try {
            await updateDoc(doc(db, `rooms/${roomId}/messages`, msg.id), {
                deletedFor: arrayUnion(currentUser.uid)
            });
        } catch (err) {
            console.error("Erro deleteForMe:", err);
            alert("Erro ao excluir mensagem.");
        }
    };

    const deleteForAll = async (msg) => {
        try {
            const data = msg;
            const seenBy = data.seenBy || [];
            if (seenBy.length > 0 || data.status === "seen") {
                return alert("Não é possível excluir para todos: mensagem já foi visualizada.");
            }

            await updateDoc(doc(db, `rooms/${roomId}/messages`, msg.id), {
                deletedForAll: true,
                text: "",
                url: "",
                type: "text",
                edited: false,
                deletedAt: serverTimestamp()
            });
        } catch (err) {
            console.error("Erro deleteForAll:", err);
            alert("Erro ao excluir para todos: " + err.message);
        }
    };

    const renderStatus = (m) => {
        if (m.from !== currentUser.uid) return null;
        if (m.deletedForAll) return null;

        const status = m.status || "sent";
        if (status === "sent") return <span style={{ marginLeft: 6, fontSize: 14 }}>✓</span>;
        if (status === "received") return <span style={{ marginLeft: 6, fontSize: 14 }}>✓✓</span>;
        if (status === "seen") return <span style={{ marginLeft: 6, fontSize: 14, color: "#19a1ff" }}>✓✓</span>;
        return null;
    };

    const findUserById = (id) => allUsers?.find(u => u.id === id);

    return (
        <>
            <div className="chat-header">
                <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                    <button onClick={onClose} style={{ background: "transparent", border: "none", color: "white", fontSize: 18 }}>←</button>
                    <Avatar user={otherUser} size={44} />
                    <div>
                        <div style={{ fontWeight: 700 }}>{otherUser.nome || otherUser.email}</div>
                        <div style={{ fontSize: 12, opacity: 0.9 }}>{otherUser.email}</div>
                    </div>
                </div>
            </div>

            <div className="chat-box" ref={listRef}>
                {messages.map(m => {
                    if (m.deletedFor && m.deletedFor.includes(currentUser.uid)) {
                        return null;
                    }

                    const isMe = m.from === currentUser.uid;
                    const sender = findUserById(m.from) || (m.from === otherUser.id ? otherUser : null);

                    if (m.deletedForAll) {
                        return (
                            <div key={m.id} style={{ display: "flex", justifyContent: isMe ? "flex-end" : "flex-start", marginBottom: 8 }}>
                                <div style={{ maxWidth: "75%", opacity: 0.8, fontStyle: "italic", color: "#666" }}>
                                    Mensagem excluída
                                </div>
                            </div>
                        );
                    }

                    return (
                        <div key={m.id} style={{ display: "flex", marginBottom: 8, alignItems: "flex-end", justifyContent: isMe ? "flex-end" : "flex-start" }}>
                            {!isMe && (
                                <div style={{ marginRight: 8 }}>
                                    <Avatar user={sender} size={36} />
                                </div>
                            )}

                            <div style={{ maxWidth: "75%" }}>
                                <div className={`msg ${isMe ? "me" : "other"}`}>

                                    {/* name for other user */}
                                    {!isMe && <div style={{ fontSize: 12, fontWeight: 700, marginBottom: 6 }}>{sender?.nome || sender?.email}</div>}

                                    {/* content */}
                                    {m.type === "image" && m.url ? (
                                        <img src={m.url} alt="img" style={{ maxWidth: 220, maxHeight: 220, borderRadius: 8 }} />
                                    ) : m.type === "video" && m.url ? (
                                        <video src={m.url} controls style={{ maxWidth: 320, maxHeight: 240, borderRadius: 8 }} />
                                    ) : m.type === "audio" && m.url ? (
                                        <audio src={m.url} controls />
                                    ) : m.type === "gif" && m.url ? (
                                        <img src={m.url} alt="gif" style={{ maxWidth: 220, borderRadius: 8 }} />
                                    ) : m.type === "file" && m.url ? (
                                        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                                            <div style={{ padding: 8, border: "1px solid #ddd", borderRadius: 8 }}>{m.url.split("/").pop()}</div>
                                        </div>
                                    ) : (
                                        <div style={{ whiteSpace: "pre-wrap" }}>{m.text}</div>
                                    )}

                                </div>

                                <div className="hora" style={{ textAlign: isMe ? "right" : "left", display: "flex", alignItems: "center", gap: 8 }}>
                                    <div style={{ flex: 1 }}>
                                        {formatTime(m.createdAt)}
                                        {m.edited && <span style={{ marginLeft: 6, fontSize: 11 }}>(editada)</span>}
                                    </div>

                                    <div>
                                        {renderStatus(m)}
                                    </div>
                                </div>
                            </div>

                            {/* ações (só para minhas mensagens) */}
                            {isMe && !m.deletedForAll && (
                                <div style={{ marginLeft: 8, display: "flex", flexDirection: "column", gap: 6 }}>
                                    <button onClick={() => startEditing(m)} title="Editar" style={{ fontSize: 12 }}>✏️</button>
                                    <button onClick={() => deleteForMe(m)} title="Excluir para mim" style={{ fontSize: 12 }}>🗑️</button>
                                    <button onClick={() => deleteForAll(m)} title="Excluir para todos" style={{ fontSize: 12 }}>🚫</button>
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>

            {/* input area */}
            <div className="chat-input" style={{ flexDirection: "column", gap: 8 }}>
                {/* preview area */}
                {previewUrl && (
                    <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
                        {file && file.type.startsWith("image/") && <img src={previewUrl} alt="preview" style={{ width: 120, height: 80, objectFit: "cover", borderRadius: 8 }} />}
                        {file && file.type.startsWith("video/") && <video src={previewUrl} style={{ width: 160, height: 100, borderRadius: 8 }} controls />}
                        <div>
                            <div style={{ fontSize: 13, fontWeight: 700 }}>{file.name}</div>
                            <div style={{ fontSize: 12, color: "#666" }}>{(file.size / 1024 / 1024).toFixed(2)} MB</div>
                        </div>
                        <button onClick={() => { setFile(null); URL.revokeObjectURL(previewUrl); setPreviewUrl(""); }}>Remover</button>
                    </div>
                )}

                {/* gif modal */}
                {showGifModal && (
                    <div style={{ padding: 8, border: "1px solid #ddd", borderRadius: 8, background: "#fff" }}>
                        <div style={{ display: "flex", gap: 8 }}>
                            <input placeholder="Cole URL do GIF aqui" value={gifUrl} onChange={e => setGifUrl(e.target.value)} style={{ flex: 1 }} />
                            <button onClick={() => setShowGifModal(false)}>Fechar</button>
                        </div>
                    </div>
                )}

                <div style={{ display: "flex", width: "100%", gap: 8, alignItems: "center" }}>
                    <button onClick={() => setShowEmoji(v => !v)} style={{ padding: 8, borderRadius: 8 }}>😊</button>

                    {showEmoji && (
                        <div style={{ position: "absolute", bottom: 80, left: 20, zIndex: 40 }}>
                            <Picker onEmojiClick={(ev, data) => setText(prev => prev + data.emoji)} />
                        </div>
                    )}

                    <input value={text} onChange={e => setText(e.target.value)} placeholder={editingMessage ? "Editando..." : "Mensagem..."} style={{ flex: 1, padding: 12, borderRadius: 25, border: "1px solid #ccc" }} />

                    <label style={{ display: "inline-flex", alignItems: "center", gap: 8, cursor: "pointer", background: "#fff", padding: "8px 12px", borderRadius: 20, border: "1px solid #ccc" }}>
                        📎
                        <input type="file" accept="image/*,video/*,audio/*,*/*" style={{ display: "none" }} onChange={onSelectFile} />
                    </label>

                    <button onClick={() => setShowGifModal(v => !v)} title="Enviar GIF por URL" style={{ padding: 8, borderRadius: 8 }}>GIF</button>

                    {/* editar controls */}
                    {editingMessage ? (
                        <>
                            <button onClick={cancelEdit} style={{ padding: 8, borderRadius: 8 }}>Cancelar</button>
                            <button onClick={saveEdit} style={{ padding: 10, borderRadius: 20, background: "#075E54", color: "#fff" }}>Salvar</button>
                        </>
                    ) : (
                        <button onClick={send} disabled={uploading} style={{ padding: "10px 16px", borderRadius: 25, background: "#075E54", color: "#fff", border: "none" }}>
                            {uploading ? "Enviando..." : "Enviar"}
                        </button>
                    )}
                </div>
            </div>
        </>
    );
}
